import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.for-each.js";
import "core-js/modules/es.iterator.map.js";
import "core-js/modules/es.iterator.reduce.js";
import AppLayout from "@/components/AppLayout.vue";
import * as echarts from "echarts";
import request from "@/utils/axios"; // 导入axios实例

export default {
  name: "AnalyticsView",
  components: {
    AppLayout
  },
  data() {
    return {
      filterForm: {
        timeRange: "30days",
        department: ["outpatient"]
      },
      trendChartType: "daily",
      charts: {
        trendChart: null,
        diseaseDistributionChart: null,
        ageDistributionChart: null,
        genderDistributionChart: null
      },
      anomalyCases: [],
      isLoading: {
        patient: false,
        diagnose: false
      },
      patientData: {
        diseaseDistribution: {},
        genderDistribution: [],
        ageDistribution: []
      },
      diagnoseData: {
        normal: [],
        unusual: []
      }
    };
  },
  methods: {
    async updateCharts() {
      await this.fetchPatientData();
      await this.fetchDiagnoseData();
      this.updateTrendChart();
      this.updateDiseaseDistributionChart();
      this.updateAgeDistributionChart();
      this.updateGenderDistributionChart();
      this.updateAnomalyCases();
    },
    resetFilter() {
      this.filterForm = {
        timeRange: "30days",
        department: ["outpatient"]
      };
      this.updateCharts();
    },
    percentFormat(percentage) {
      return percentage + "%";
    },
    getConfidenceColor(confidence) {
      if (confidence < 60) {
        return "#F56C6C";
      } else if (confidence < 80) {
        return "#E6A23C";
      } else {
        return "#67C23A";
      }
    },
    viewAnomalyDetail(row) {
      this.$router.push(`/reports/detail/${row.id}`);
    },
    exportData(type) {
      this.$message.success(`数据已导出为${type.toUpperCase()}格式`);
    },
    // 获取患者相关数据
    async fetchPatientData() {
      this.isLoading.patient = true;
      try {
        // 计算时间范围
        const time = this.getTimeRangeValue();
        const response = await request({
          method: "get",
          url: "/diagram/show/patient",
          params: {
            time
          }
        });
        if (response.code === 1) {
          // 保存API返回的数据
          const {
            diseaseDistribution,
            genderDistribution,
            ageDistribution
          } = response.data;
          this.patientData = {
            diseaseDistribution,
            genderDistribution,
            ageDistribution
          };
        } else {
          this.$message.error(response.msg || "获取患者数据失败");
        }
      } catch (error) {
        console.error("获取患者数据出错:", error);
        this.$message.error("获取患者数据失败，请稍后重试");
      } finally {
        this.isLoading.patient = false;
      }
    },
    // 获取诊断趋势数据
    async fetchDiagnoseData() {
      this.isLoading.diagnose = true;
      try {
        // 根据选择的时间类型设置参数
        let timeType;
        switch (this.trendChartType) {
          case "daily":
            timeType = "日";
            break;
          case "weekly":
            timeType = "周";
            break;
          case "monthly":
            timeType = "月";
            break;
          default:
            timeType = "日";
        }

        // 创建FormData对象
        const formData = new FormData();
        formData.append("timeType", timeType);
        const response = await request({
          method: "post",
          url: "/diagram/show/diagnose",
          headers: {
            "Content-Type": "multipart/form-data"
          },
          data: formData
        });
        if (response.code === 1) {
          // 保存API返回的数据
          this.diagnoseData = {
            normal: response.data.normal || [],
            unusual: response.data.unusual || []
          };

          // 更新趋势图表
          this.updateTrendChart();
        } else {
          this.$message.error(response.msg || "获取诊断趋势数据失败");
        }
      } catch (error) {
        console.error("获取诊断趋势数据出错:", error);
        this.$message.error("获取诊断趋势数据失败，请稍后重试");
      } finally {
        this.isLoading.diagnose = false;
      }
    },
    // 根据选择的时间范围返回实际天数
    getTimeRangeValue() {
      switch (this.filterForm.timeRange) {
        case "7days":
          return 7;
        case "30days":
          return 30;
        case "3months":
          return 90;
        case "1year":
          return 365;
        default:
          return 30;
      }
    },
    // 诊断趋势图表
    async updateTrendChart() {
      await this.fetchDiagnoseData();
      if (!this.charts.trendChart) {
        this.charts.trendChart = echarts.init(this.$refs.trendChart);
      }

      // 使用API返回的数据
      const normalCounts = this.diagnoseData.normal || [];
      const abnormalCounts = this.diagnoseData.unusual || [];

      // 生成日期标签
      const dates = [];
      const dataLength = Math.max(normalCounts.length, abnormalCounts.length);
      for (let i = 0; i < dataLength; i++) {
        let dateStr;
        if (this.trendChartType === "daily") {
          dateStr = `第${i + 1}日`;
        } else if (this.trendChartType === "weekly") {
          dateStr = `第${i + 1}周`;
        } else {
          dateStr = `第${i + 1}月`;
        }
        dates.push(dateStr);
      }

      // 计算总诊断量
      const diagnosisCounts = normalCounts.map((count, index) => {
        return count + (abnormalCounts[index] || 0);
      });
      const option = {
        tooltip: {
          trigger: "axis",
          axisPointer: {
            type: "shadow"
          },
          formatter: function (params) {
            let result = params[0].name + "<br/>";
            let total = 0;
            params.forEach(param => {
              total += param.value;
              result += param.seriesName + ": " + param.value + "<br/>";
            });
            if (params[0].seriesName !== "总诊断量") {
              result = params[0].name + "<br/>总诊断量: " + total + "<br/>" + result;
            }
            return result;
          }
        },
        legend: {
          data: ["总诊断量", "正常", "异常"]
        },
        grid: {
          left: "3%",
          right: "4%",
          bottom: "3%",
          containLabel: true
        },
        xAxis: {
          type: "category",
          data: dates,
          axisLabel: {
            interval: 0,
            rotate: 45
          }
        },
        yAxis: {
          type: "value",
          name: "诊断数量",
          minInterval: 1
        },
        series: [{
          name: "总诊断量",
          type: "line",
          data: diagnosisCounts,
          smooth: true,
          lineStyle: {
            width: 3
          },
          itemStyle: {
            color: "#409EFF"
          }
        }, {
          name: "正常",
          type: "bar",
          stack: "total",
          data: normalCounts,
          itemStyle: {
            color: "#67C23A"
          }
        }, {
          name: "异常",
          type: "bar",
          stack: "total",
          data: abnormalCounts,
          itemStyle: {
            color: "#F56C6C"
          }
        }]
      };
      this.charts.trendChart.setOption(option);
    },
    // 疾病分布图表
    updateDiseaseDistributionChart() {
      if (!this.charts.diseaseDistributionChart) {
        this.charts.diseaseDistributionChart = echarts.init(this.$refs.diseaseDistributionChart);
      }

      // 使用API返回的疾病分布数据
      const diseaseData = this.patientData.diseaseDistribution || {};

      // 构造图表数据
      const categories = ["N", "D", "G", "C", "A", "H", "M", "O"];
      const diseaseNames = {
        N: "正常",
        D: "糖尿病视网膜病变",
        G: "青光眼",
        C: "白内障",
        A: "AMD",
        H: "高血压视网膜病变",
        M: "近视",
        O: "其他异常"
      };
      const data = [];
      for (const key in diseaseData) {
        if (categories.includes(key)) {
          data.push({
            name: diseaseNames[key],
            value: parseFloat((diseaseData[key] * 100).toFixed(1))
          });
        }
      }
      const option = {
        tooltip: {
          trigger: "item",
          formatter: "{a} <br/>{b}: {c}%"
        },
        legend: {
          orient: "vertical",
          right: 10,
          top: "center",
          data: Object.values(diseaseNames)
        },
        series: [{
          name: "疾病分布",
          type: "pie",
          radius: ["50%", "70%"],
          avoidLabelOverlap: false,
          label: {
            show: false,
            position: "center"
          },
          emphasis: {
            label: {
              show: true,
              fontSize: "16",
              fontWeight: "bold"
            }
          },
          labelLine: {
            show: false
          },
          data: data
        }]
      };
      this.charts.diseaseDistributionChart.setOption(option);
    },
    // 年龄分布图表
    updateAgeDistributionChart() {
      if (!this.charts.ageDistributionChart) {
        this.charts.ageDistributionChart = echarts.init(this.$refs.ageDistributionChart);
      }

      // 使用API返回的年龄分布数据
      const ageDistribution = this.patientData.ageDistribution || [];

      // 构造年龄组
      const ageGroupLabels = ["0-18", "19-30", "31-45", "46-60", "61-75", "76+"];

      // 确保数据长度匹配
      const data = ageDistribution.slice(0, ageGroupLabels.length);

      // 如果数据长度不足，补充0
      while (data.length < ageGroupLabels.length) {
        data.push(0);
      }
      const option = {
        tooltip: {
          trigger: "axis",
          axisPointer: {
            type: "shadow"
          }
        },
        grid: {
          left: "3%",
          right: "4%",
          bottom: "3%",
          containLabel: true
        },
        xAxis: {
          type: "category",
          data: ageGroupLabels
        },
        yAxis: {
          type: "value",
          name: "患者数量"
        },
        series: [{
          name: "患者数量",
          type: "bar",
          data: data,
          itemStyle: {
            color: function (params) {
              const colorList = ["#91c7ae", "#749f83", "#ca8622", "#bda29a", "#6e7074", "#546570"];
              return colorList[params.dataIndex];
            }
          }
        }]
      };
      this.charts.ageDistributionChart.setOption(option);
    },
    // 性别分布图表
    updateGenderDistributionChart() {
      if (!this.charts.genderDistributionChart) {
        this.charts.genderDistributionChart = echarts.init(this.$refs.genderDistributionChart);
      }

      // 使用API返回的性别分布数据
      const genderDistribution = this.patientData.genderDistribution || [];

      // 确保有两个值(男/女)
      const maleCount = genderDistribution[0] ? genderDistribution[0] * 100 : 0;
      const femaleCount = genderDistribution[1] ? genderDistribution[1] * 100 : 0;
      const option = {
        tooltip: {
          trigger: "item",
          formatter: "{a} <br/>{b}: {c}%"
        },
        legend: {
          orient: "horizontal",
          bottom: "bottom",
          data: ["男", "女"]
        },
        color: ["#409EFF", "#FF6B6B"],
        series: [{
          name: "性别分布",
          type: "pie",
          radius: "55%",
          center: ["50%", "45%"],
          data: [{
            value: maleCount,
            name: "男"
          }, {
            value: femaleCount,
            name: "女"
          }],
          emphasis: {
            itemStyle: {
              shadowBlur: 10,
              shadowOffsetX: 0,
              shadowColor: "rgba(0, 0, 0, 0.5)"
            }
          }
        }]
      };
      this.charts.genderDistributionChart.setOption(option);
    },
    // 更新异常病例数据
    updateAnomalyCases() {
      // 根据异常趋势数据生成模拟的异常病例
      const totalAbnormal = this.diagnoseData.unusual.reduce((sum, cur) => sum + cur, 0);
      const count = Math.min(5, totalAbnormal);
      this.anomalyCases = [];
      const diseaseOptions = ["糖尿病视网膜病变", "青光眼", "白内障", "AMD", "高血压视网膜病变", "近视", "其他异常", "正常"];
      for (let i = 0; i < count; i++) {
        const date = new Date();
        date.setDate(date.getDate() - Math.floor(Math.random() * 30));
        const leftConfidence = Math.floor(Math.random() * 30) + 40; // 40-70之间
        const rightConfidence = Math.floor(Math.random() * 30) + 40;
        const leftDiagnosis = diseaseOptions[Math.floor(Math.random() * diseaseOptions.length)];
        const rightDiagnosis = diseaseOptions[Math.floor(Math.random() * diseaseOptions.length)];
        let anomalyReason;
        if (leftConfidence < 60 && rightConfidence < 60) {
          anomalyReason = "双眼诊断置信度低";
        } else if (leftConfidence < 60) {
          anomalyReason = "左眼诊断置信度低";
        } else if (rightConfidence < 60) {
          anomalyReason = "右眼诊断置信度低";
        } else if (leftDiagnosis !== rightDiagnosis && leftDiagnosis !== "正常" && rightDiagnosis !== "正常") {
          anomalyReason = "左右眼诊断结果差异大";
        }
        this.anomalyCases.push({
          id: `PT2023${2000 + i}`,
          time: date.toLocaleString(),
          leftEye: {
            diagnosis: leftDiagnosis,
            confidence: leftConfidence
          },
          rightEye: {
            diagnosis: rightDiagnosis,
            confidence: rightConfidence
          },
          anomalyReason: anomalyReason
        });
      }
    }
  },
  mounted() {
    // 检查登录状态
    const isLoggedIn = localStorage.getItem("isLoggedIn");
    if (!isLoggedIn) {
      this.$router.push("/login");
    }

    // 初始化图表
    this.$nextTick(() => {
      this.updateCharts();

      // 响应窗口大小变化
      window.addEventListener("resize", () => {
        for (const key in this.charts) {
          if (this.charts[key]) {
            this.charts[key].resize();
          }
        }
      });
    });
  },
  beforeUnmount() {
    // 移除事件监听
    window.removeEventListener("resize", () => {});

    // 销毁图表实例
    for (const key in this.charts) {
      if (this.charts[key]) {
        this.charts[key].dispose();
      }
    }
  }
};
